	private static int activeReaders(long environment) {
		AtomicInteger count = new AtomicInteger();
		MDBMsgFunc callback = MDBMsgFunc.create((message, context) -> {
			count.incrementAndGet();
			return 0;
		});
		try (MemoryStack stack = stackPush()) {
			long context = memAddress(stack.mallocPointer(1));
			assertEquals(MDB_SUCCESS, mdb_reader_list(environment, callback, context));
		} finally {
			callback.free();
		}
		return count.get();
	}

	private static boolean reaches(Throwable root, Throwable target) {
		Set<Throwable> seen = Collections.newSetFromMap(new IdentityHashMap<>());
		ArrayDeque<Throwable> pending = new ArrayDeque<>();
		pending.add(root);
		while (!pending.isEmpty()) {
			Throwable current = pending.removeFirst();
			if (!seen.add(current)) {
				continue;
			}
			if (current == target) {
				return true;
			}
			if (current.getCause() != null) {
				pending.addLast(current.getCause());
			}
			for (Throwable suppressed : current.getSuppressed()) {
				pending.addLast(suppressed);
			}
		}
		return false;
	}

